[2751] = { en = "Barbaric Battlements", tier = 2,
  t = "Barbaarse borstweringen",
  d = "Twintig generaties Omosh hebben deze hamer vastgehouden, $N. Honderdduizend ton metaal hebben we gevormd. Helaas eindigt het allemaal bij Orokk, de mislukking van de Omosh: zonder familie en niet in staat om kinderen te krijgen.$B$BIk kan de geheime recepten van de Omosh niet met mij laten sterven! Iemand moet de erfenis voortzetten, Omosh of niet!$B$BBewijs aan Orokk dat je het kunt, $N. Breng voor Orokk het volgende: twee patterned bronze bracers, twee bronze greatswords en twee sharp claws. Breng ze voor Orokk en dan gaan we verder.",
  o = "Breng twee Patterned Bronze Bracers, twee Bronze Greatswords en twee Sharp Claws naar Orokk Omosh in Orgrimmar.$b",
  p = "Brons, $N! Meer brons!!",
  c = "De familielijn zal verdwijnen, maar misschien leeft de legende van de Omosh verder!$B$BJe hebt bewezen dat je een smid bent, $N. De beloning van een smid is de voldoening als hij zijn wapens en harnassen bedekt ziet met het bloed van zijn vijanden!$B$BMogen de borstplaten die jij maakt voor de komende generaties doordrenkt zijn met het bloed van je vijanden!",
  g = { {"borstweringen", "battlements (borstwering)"}, {"gevormd", "molded, shaped (vormen)"}, {"mislukking", "failure"}, {"niet in staat", "incapable, not able"}, {"erfenis", "legacy, inheritance"}, {"voortzetten", "continue"}, {"smid", "blacksmith"}, {"voldoening", "satisfaction"}, {"harnassen", "armors (harnas)"}, {"borstplaten", "breastplates (borstplaat)"}, {"doordrenkt", "drenched, soaked"} },
},

[2752] = { en = "On Iron Pauldrons", tier = 2,
  t = "Over ijzeren schouderstukken",
  d = "Orokk ziet de gretigheid in je ogen, $N. Als een spons zuig je de wijsheid van de Omosh op.$B$BDrie lessen zal ik je leren!$B$BGa terug naar het aambeeld, neem de hitte van de smidse in je op, en maak voor Orokk vier bronze battleaxes en vier bronze warhammers. Pas dan leer je over het ijzeren schouderstuk.",
  o = "Breng vier Bronze Battleaxes en vier Bronze Warhammers naar Orokk Omosh in Orgrimmar.",
  p = "Laat me je toewijding zien, $R.",
