[1051] = { en = "Vorrel's Revenge", tier = 2,
  t = "De wraak van Vorrel",
  d = "Mijn wil is nu vrij, maar toch kan ik de Dark Lady niet langer dienen. Ik voel dat mijn tijd op Azeroth voorbij is. Mijn levenskracht is gebroken.$b$bInterrogator Vishas heeft me dit aangedaan! Hij heeft me wekenlang gemarteld! Hij heeft mijn trouwring gepakt en aan zijn vrouw gegeven. De schoft!$b$bWraak... Ik wil wraak!$b$bDie verwaande dwaas schepte op over zijn dierbare vrouw, Nancy, die aan Lake Lordamere woonde. Spoor dat wijf op, dood haar en breng mijn trouwring terug naar mijn vrouw, Monika in Tarren Mill.$b$bLuister naar mijn laatste wensen....",
  o = "Breng de trouwring van Vorrel Sengutz terug naar Monika Sengutz in Tarren Mill.",
  p = "Wat wil je, vreemdeling?",
  c = "Vorrel had zo'n moeilijk bestaan. En wat was hij een goede partner...$b$bVervloekt zijn die smerige mensen!$b$bVorrel is weg en zal nooit meer van zijn ondode leven genieten. Ik vind tenminste troost in de wraak die jij in zijn naam hebt genomen. Daarvoor dank ik je.$b$bLaat me nu alleen om te rouwen....",
  g = { {"wraak", "revenge"}, {"levenskracht", "life force"}, {"gemarteld", "tortured (martelen)"}, {"trouwring", "wedding ring"}, {"schoft", "bastard"}, {"verwaande", "pompous, conceited (verwaand)"}, {"schepte op", "bragged (opscheppen)"}, {"spoor ... op", "track down (opsporen)"}, {"wijf", "wench"}, {"bestaan", "existence"}, {"troost", "solace, comfort"}, {"rouwen", "mourn"} },
},

[1113] = { en = "Hearts of Zeal", tier = 2,
  t = "Fanatieke harten",
  d = "Waarom ik een zeldzaam soort guano nodig heb, vraag je je misschien af? Nou, bij dit experiment wil ik zien wat twee totaal tegengestelde chemische stoffen met elkaar doen. Vooral als ze allebei gemengd worden met een altijd giftig middel, voor de meest... gruwelijke resultaten.$b$bIn de bergtoppen in het noordoosten van Tirisfal Glades ligt het Scarlet Monastery. Daar komen de gestoorde volgelingen van de Scarlet Crusade samen. Dood ze en breng me hun fanatieke harten.$b$bOns brouwsel wordt heel kwaadaardig!",
  o = "Master Apothecary Faranell in Undercity wil 20 Hearts of Zeal.",
  p = "Ben je terug van het Scarlet Monastery? Ik heb veel harten nodig voor dit heerlijke experiment!$b$bVarimathras en de Dark Lady zullen zonder twijfel ook blij zijn als ze van dat Scarlet-tuig af zijn...",
  c = "Wat een overvloed aan bloederige resten heb je me gebracht, $n! Je hebt het uitstekend gedaan!",
  g = { {"fanatieke", "zealous, fanatical (fanatiek)"}, {"zeldzaam", "rare"}, {"tegengestelde", "opposed (tegengesteld)"}, {"stoffen", "substances (stof)"}, {"giftig", "toxic"}, {"gruwelijke", "ghastly (gruwelijk)"}, {"bergtoppen", "peaks (bergtop)"}, {"gestoorde", "crazed (gestoord)"}, {"volgelingen", "disciples, followers (volgeling)"}, {"brouwsel", "concoction, brew"}, {"kwaadaardig", "wicked, evil"}, {"tuig", "scum, riffraff"}, {"overvloed", "abundance"}, {"bloederige", "gory, bloody (bloederig)"} },
},

[535] = { en = "Valik", tier = 2,
  t = "Valik",
  d = "Uurgh... Gewond, stervend en tegenover de vijand.$b$bJe zult me toch wel doden. Maar als je me wat Southshore stout brengt (jouw soort drinkt toch wel?), dan vertel ik je wat je wilt weten.",
  o = "Breng een mok Southshore Stout naar Valik in het kamp van de Syndicate.",
  p = "Heb je iets te drinken voor me meegebracht, of kom je terug om het af te maken?",
  c = "Nu ik binnenkort ga sterven, kan ik wel zeggen dat dit het lekkerste is dat ik ooit heb geproefd... Hier, neem dit. Het heeft voor mij geen nut als ik dood ben.$B$BKom op, maak het af!",
  g = { {"gewond", "injured"}, {"stervend", "dying"}, {"tegenover", "facing, confronted with"}, {"mok", "mug"}, {"meegebracht", "brought along (meebrengen)"}, {"af te maken", "to finish (afmaken)"}, {"binnenkort", "soon"}, {"geproefd", "tasted (proeven)"}, {"nut", "use, good"} },
},

[581] = { en = "Hunt for Yenniku", tier = 2,
  t = "De jacht op Yenniku",
  d = "Er is een onheil. Een onheil op de jongste zoon van mijn opperhoofd, Yenniku. Zoals de gewoonte is bij ons volk, werd hij aan de Gurubashi-trollen van Zul'Gurub gegeven. Maar nadat mijn stam, de Darkspear-stam, met de orc Thrall vertrok, waren we de arme Yenniku kwijt. Ik werd vanuit het verre Orgrimmar teruggestuurd naar Stranglethorn om de zoon van mijn opperhoofd te zoeken.$B$BEn ik denk dat de Bloodscalp-stam hem heeft.$B$BAls je me wilt helpen, jaag dan op de Bloodscalps. Je kunt ze in het noorden vinden. Verzamel hun slagtanden en kom terug bij mij.",
  o = "Breng 9 Bloodscalp Tusks naar Nimboya in het Grom'gol Base Camp.",
  p = "$C. Laat me zien dat je op de Bloodscalp-stam hebt gejaagd.$B$BLaat me je trofeeën zien.",
  c = "Dit zijn goede slagtanden, $N. Je bewijst dat je sterk genoeg bent om op de Bloodscalps te jagen.$B$BEn dat is goed, want je bent nog niet klaar met de jacht op hen.",
  g = { {"jacht", "hunt"}, {"onheil", "doom, disaster"}, {"opperhoofd", "chief"}, {"gewoonte", "custom"}, {"stam", "tribe"}, {"kwijt", "lost"}, {"verre", "distant (ver)"}, {"teruggestuurd", "sent back (terugsturen)"}, {"jaag", "hunt (jagen)"}, {"slagtanden", "tusks (slagtand)"}, {"trofeeën", "trophies (trofee)"} },
},

[2949] = { en = "Return of the Ring", tier = 2,
  t = "De terugkeer van de ring",
  d = "Je opent de doos die de Sparklematic 5200 heeft gemaakt, en je ziet een glimmende ring! Je doet de ring om en je voelt magische kracht door je lichaam stromen.$B$BAan de binnenkant van de ring zit een kleine maar toch duidelijke afdruk van het zegel van Orgrimmar. Er staan gegraveerde letters naast, maar zelfs na het schoonmaken zijn alleen de eerste drie goed te zien: \"NOG...\"$B$BDit kunnen de initialen van de vorige eigenaar zijn, of misschien de initialen van de maker van de ring. Houd de ring... of zoek \"NOG\". Keuzes, keuzes...",
  o = "Je mag de ring houden, of je kunt de persoon zoeken die verantwoordelijk is voor de afdruk en de letters aan de binnenkant van de ring.",
  p = "Je zou denken dat we zelf wel een manier vinden om die smerige kleine gnomen te overtreffen. Ik durf zelfs te wedden dat ze die machine in het begin van ons hebben gestolen! Bah, die vette, vieze... ehm, ja? Heb je iets nodig?",
  c = "Een ring uit Gnomeregan? Eens kijken... niet van mij, maar wel interessant.$B$BDat gedoe met Gnomeregan: het kon geen aardiger stelletje sukkels overkomen. Jarenlang zijn ze een grap, en nu maken ze bijna van de ene op de andere dag betere machines dan wij?$B$BHadden Dark Iron-dwergen de ring? Dat is nog interessanter! Weet je, misschien hebben de gnomen hun gekke golemplannen gestolen en aangepast. Die Dark Irons zouden zeker flink wraak willen nemen. Het is zeker de moeite waard om dat te onderzoeken.$B$BWeet je, over die ring...",
  g = { {"glimmende", "shiny (glimmend)"}, {"doet ... om", "put on (omdoen)"}, {"stromen", "surge, flow"}, {"binnenkant", "inside"}, {"afdruk", "imprint"}, {"gegraveerde", "engraved (gegraveerd)"}, {"initialen", "initials"}, {"eigenaar", "owner"}, {"overtreffen", "outdo, surpass"}, {"wedden", "wager, bet"}, {"stelletje", "bunch"}, {"sukkels", "numbskulls (sukkel)"}, {"aangepast", "modified (aanpassen)"}, {"de moeite waard", "worth it"} },
},

[568] = { en = "The Defense of Grom'gol", tier = 3,
  t = "De verdediging van Grom'gol",
  d = "Throm'ka, $c!$b$bJe komt precies op het goede moment naar Grom'gol. Als commandant van het basiskamp van de Warchief hier in de jungle ben ik door mijn eer verplicht om te zorgen voor de veiligheid van alle leden van de Horde. Onze missie is een veilige aanvoerroute naar Stonard, maar sommige bewoners van deze streek hinderen ons daarbij.$b$bIk geef jou de leiding over het uitdunnen van het aantal raptors buiten Grom'gol. Als je flinke vooruitgang hebt geboekt, meld je dan weer bij mij voor een nieuwe opdracht.",
  o = "Commander Aggro'gosh van het Grom'gol-basiskamp wil dat je 15 Lashtail Raptors doodt.",
  p = "Onze bevoorrading wordt nog steeds gehinderd door de raptors die hier leven, $c.",
  c = "Je hebt je plicht met eer vervuld, $c.",
  g = { {"verdediging", "defense"}, {"basiskamp", "base camp"}, {"verplicht", "bound, obliged"}, {"aanvoerroute", "supply route"}, {"bewoners", "inhabitants (bewoner)"}, {"streek", "region, area"}, {"hinderen", "hamper, hinder"}, {"uitdunnen", "thinning out"}, {"vooruitgang geboekt", "made progress (vooruitgang boeken)"}, {"meld je", "report (zich melden)"}, {"bevoorrading", "supply"}, {"plicht", "duty"}, {"vervuld", "fulfilled, performed (vervullen)"} },
},

[1160] = { en = "Test of Lore", tier = 3,
  t = "Een test van kennis",
  d = "Ik zal je vertellen wat je moet zoeken, en ik zal je zelfs mijn vraag stellen. Maar niet omdat jij jezelf wilt bewijzen. Kennis is veel belangrijker dan kracht. Ook als anderen je voorbijgaan in vaardigheid, zal jouw kennis van de wereld meer waard zijn.$B$BGa naar het klooster in het noorden van Tirisfal Glades. In de bibliotheek daar staat een boek dat Beginnings of the Undead Threat heet. De paladijnen daar, die nu verdorven zijn, gebruikten het om te leren vechten tegen mijn soort.$B$BBreng het naar mij.",
  o = "Zoek The Beginnings of the Undead Threat en breng het terug naar Parqual Fintallas in Undercity.",
  p = "Ik hoop dat je de Scarlet Crusade een beetje hebt laten lijden voordat je het boek van hen stal.$b$bMijn mening over hun soort is niet ongegrond. De Crusade volgde misschien ooit het Licht, maar nu willen ze alle wezens vernietigen die niet de kant van hun geloof hebben gekozen. Ze geloven dat alle ondoden, Forsaken of niet, gereinigd moeten worden. En wie door hun land reist, is volgens hen gek, of in de macht van de sterke magie van de ondoden. Idioten. Idioten en dwazen, allemaal.",
  c = "Dit is het boek waarnaar ik je heb gestuurd.$b$b<Parqual strijkt langzaam met zijn hand over het boek terwijl hij ernaar kijkt.>$b$bDus nu wil je een vraag om te bewijzen dat je verstand net zo sterk is als je lichaam en je geest. Als je het boek lang genoeg hebt bestudeerd, dan zal ik je je vraag stellen, en dan ben je klaar met deze tests!",
  g = { {"kennis", "knowledge, lore"}, {"bewijzen", "prove"}, {"voorbijgaan", "pass by"}, {"vaardigheid", "ability, skill"}, {"klooster", "monastery"}, {"verdorven", "corrupt"}, {"ongegrond", "unwarranted, unfounded"}, {"geloof", "religion, faith"}, {"gereinigd", "cleansed (reinigen)"}, {"dwazen", "fools (dwaas)"}, {"strijkt", "strokes, runs (strijken)"}, {"verstand", "mind, intellect"}, {"bestudeerd", "studied (bestuderen)"} },
},

[2753] = { en = "Trampled Under Foot", tier = 3,
  t = "Onder de voet gelopen",
  d = "Nog maar twee lessen zal Orokk je leren, $N. Je spieren doen pijn, dat weet ik, maar ga door voor de Omosh!$B$BBreng Orokk vier green iron helms, vier green iron bracers en twee green iron leggings. Hiermee leer jij iets en lijden je vijanden!",
  o = "Breng vier Green Iron Helms, vier Green Iron Bracers en twee Green Iron Leggings naar Orokk Omosh in Orgrimmar.",
  p = "Hun schedels zullen kraken onder de druk van je laarzen!",
  c = "Je doet Orokk denken aan zijn grootvader, opperhoofd Gorokk van de Omosh! Lees, leer over de ijzeren laars.",
  g = { {"onder de voet gelopen", "trampled under foot"}, {"spieren", "muscles (spier)"}, {"lijden", "suffer"}, {"schedels", "skulls (schedel)"}, {"kraken", "crack"}, {"druk", "pressure"}, {"laarzen", "boots (laars)"}, {"opperhoofd", "chief"}, {"doet ... denken aan", "reminds of (doen denken aan)"} },
},

[2754] = { en = "Horns of Frenzy", tier = 3,
  t = "Hoorns van razernij",
  d = "Dit is de laatste les die Orokk je leert, $N. Ga terug naar het heilige aambeeld en de smidse! Breng Orokk twee solid iron mauls, twee silvered bronze boots en twee silvered bronze gauntlets.$B$BZie de angst in hun ogen als je dichterbij komt!$b",
  o = "Breng twee Solid Iron Mauls, twee Silvered Bronze Boots en twee Silvered Bronze Gauntlets naar Orokk Omosh in Orgrimmar.",
  p = "Laat het ijzer zien wie de baas is, $N!",
  c = "Verbazingwekkend! Je hebt de weg van de Omosh geleerd, $N!",
