[2755] = { en = "Joys of Omosh", tier = 3,
  t = "De vreugde van de Omosh",
  d = "Orokk huilt niet, $N. Roet zit in oog.$B$B<Orokk veegt een traan weg.>$B$BEr is nog één laatste familiegeheim van de Omosh dat Orokk je zal leren. Orokk zal blij sterven, dankzij $N.$B$BLeer de vreugdedans van de Omosh en dan leer je de vuist van ijzer!$b",
  o = "Kijk en leer de Omosh Dance of Joy.",
  c = "<Orokk hijgt.>$B$BHet is heel lang geleden dat Orokk de vreugdedans van de Omosh heeft gedaan. Leer nu, $N!",
  e = "Omosh Dance of Joy geleerd",
  g = { {"vreugde", "joy"}, {"roet", "soot"}, {"veegt ... weg", "wipes away (wegvegen)"}, {"traan", "tear"}, {"familiegeheim", "family secret"}, {"vreugdedans", "dance of joy"}, {"vuist", "fist"}, {"hijgt", "pants (hijgen)"} },
},

[569] = { en = "The Defense of Grom'gol", tier = 3,
  t = "De verdediging van Grom'gol",
  d = "Toen we in deze jungle aankwamen, waren we niet van plan om oorlog te voeren tegen de stammen hier. Onze missie om Stonard te bevoorraden heeft de hoogste prioriteit. Maar er zijn complicaties ontstaan. Een groep ogres uit de streek heeft de Mizjah Ruins ten zuidoosten van Grom'gol bezet. Ondanks onze waarschuwingen blijven ze onze karavanen met voorraden overvallen.$b$bIk geef jou de leiding over het aanpakken van deze ogres, die niet willen meewerken.$b$bReis naar de ruïnes en probeer ze uit het gebied te verdrijven. Dan sturen we op zijn minst een duidelijke boodschap.",
  o = "Commander Aggro'gosh van het Grom'gol-basiskamp wil dat je 10 Ogre Brutes en 5 Ogre Witch Doctors doodt.",
  p = "Heb je al vooruitgang geboekt met de ogres van de Mizjah Ruins, $c?",
  c = "Goed gedaan. Je hebt de Warchief met eer gediend.",
  g = { {"oorlog te voeren", "to wage war (oorlog voeren)"}, {"bevoorraden", "supply"}, {"ontstaan", "arisen (ontstaan)"}, {"bezet", "occupied (bezetten)"}, {"ondanks", "despite"}, {"karavanen", "caravans (karavaan)"}, {"overvallen", "ambush, raid"}, {"aanpakken", "dealing with, tackling"}, {"meewerken", "cooperate"}, {"verdrijven", "drive out"}, {"op zijn minst", "at the very least"}, {"boodschap", "message"} },
},

[582] = { en = "Headhunting", tier = 3,
  t = "Koppensnellen",
  d = "We moeten weten of Yenniku dood is.$B$BDood de Bloodscalp Headhunters en neem hun Shrunken Heads. Je moet heel veel hoofden verzamelen, en ik zal ze bekijken om zeker te weten dat het hoofd van Yenniku er niet tussen zit.$B$BEn als Yenniku door de Bloodscalps is gedood, dan moge er een vloek van 600 jaar vallen op de geest van hun opperhoofd, Gan'zulah!$B$BGa, $N. Je kunt veel Headhunters vinden bij de ruïnes van Zuuldaia en Zul'Kunda, langs de kust in het noorden.",
  o = "Breng 20 Shrunken Heads naar Nimboya in het Grom'gol Base Camp.",
  p = "$N. Ik ben bang voor de zoon van ons opperhoofd. Heb je de gekrompen hoofden, zodat ik ze kan bekijken?",
  c = "Dank je, $N. Ik zal deze hoofden bekijken om zeker te weten dat de arme Yenniku de bijl van de koppensnellers bespaard is gebleven.",
  g = { {"koppensnellen", "headhunting"}, {"er niet tussen zit", "is not among them (tussen zitten)"}, {"moge", "may (archaic subjunctive of mogen)"}, {"vloek", "curse"}, {"geest", "spirit"}, {"opperhoofd", "chief"}, {"kust", "coast"}, {"gekrompen", "shrunken (krimpen)"}, {"bijl", "axe"}, {"koppensnellers", "headhunters (koppensneller)"}, {"bespaard is gebleven", "was spared (bespaard blijven)"} },
},

[1049] = { en = "Compendium of the Fallen", tier = 3,
  t = "Het compendium van de gevallenen",
  d = "De Earthen Ring had zuivere bedoelingen met onze broeders die door de pest getroffen zijn. Maar wie weet wat de motieven zijn van degenen die in de oren van de Elder Council fluisteren?$b$bDe Forsaken met wie we een bondgenootschap hebben, hebben een geschiedenis vol bedrog. Ons verbond was te haastig. Misschien was het verstandig geweest als Cairne naar de waarschuwingen uit Orgrimmar had geluisterd.$b$bDiep in het Scarlet Monastery ligt het Compendium of the Fallen, bewaakt door gestoorde menselijke fanatici. Hun methode komt voort uit waanzin, maar hun onderzoek kan nuttig blijken.",
  o = "Haal het Compendium of the Fallen uit het klooster in Tirisfal Glades en ga terug naar Sage Truthseeker in Thunder Bluff.",
  p = "Cairne is een dappere en edele leider, en ik zou hem mijn eigen leven toevertrouwen. Maar anderen vertrouw ik niet in dit politieke klimaat.$b$bZodra ik de kans heb gehad om alle beschikbare kennis te verzamelen, kan ik het opperhoofd goed advies geven.$b$bBen je al naar Tirisfal Glades gereisd? Naar het Scarlet Monastery? Het Compendium of the Fallen is maar één stukje van deze ingewikkelde puzzel...",
  c = "Het Compendium of the Fallen! Ik begon me al af te vragen of het boek wel echt bestond!$b$bJe hebt de tauren van Thunder Bluff goed gediend, $n. Je toewijding zal niet vergeten worden.",
  g = { {"gevallenen", "the fallen (gevallene)"}, {"zuivere", "pure (zuiver)"}, {"bedoelingen", "intentions (bedoeling)"}, {"getroffen", "struck, afflicted (treffen)"}, {"bondgenootschap", "alliance"}, {"bedrog", "deceit"}, {"verbond", "pact"}, {"haastig", "hasty"}, {"verstandig", "wise, sensible"}, {"fanatici", "zealots (fanaticus)"}, {"waanzin", "insanity"}, {"toevertrouwen", "entrust"}, {"opperhoofd", "chieftain"}, {"ingewikkelde", "complicated (ingewikkeld)"} },
},

[673] = { en = "Foul Magics", tier = 3,
  t = "Duistere magie",
  d = "Ik twijfel er niet aan dat er een machtige heksenmeester binnen de muren van Stromgarde woont. Af en toe gebruikt deze heksenmeester een arcaan magisch relikwie om grote aantallen vreselijke demonen op te roepen. We moeten de bron van zijn kracht weghalen.$b$bZoek de heksenmeester en dood hem. Breng me het magische voorwerp dat je bij hem vindt. Dan zal ik ervoor zorgen dat het wordt vernietigd, zodat de kracht ervan dit land niet langer bezoedelt.",
  o = "Haal Marez Cowl's Bloodstone Orb op en breng hem naar Tor'gan in Hammerfall.",
  p = "Het branden in mijn bloed... het wordt elke dag erger. De heksenmeester moet worden tegengehouden.",
  c = "Als ik deze bol heb vernietigd, worden mijn onrustige nachten weer een vredige slaap. Dank je, $N. De bol is een huiveringwekkende herinnering aan de vreselijke macht die de demonen over de orcs hadden, voordat Hellscream hen van hun vloek bevrijdde.",
  g = { {"heksenmeester", "warlock"}, {"relikwie", "relic"}, {"op te roepen", "to summon (oproepen)"}, {"bron", "source"}, {"vernietigd", "destroyed (vernietigen)"}, {"bezoedelt", "taints, defiles (bezoedelen)"}, {"onrustige", "restless (onrustig)"}, {"vredige", "peaceful (vredig)"}, {"huiveringwekkende", "chilling (huiveringwekkend)"}, {"vloek", "curse"}, {"bevrijdde", "freed (bevrijden)"} },
},

[679] = { en = "Call to Arms", tier = 3,
  t = "Te wapen",
  d = "De kop van het beest is klaar om eraf gehaald te worden... met veel geweld, $N. Je hebt alle tekenen laten zien dat je ons kunt helpen bij deze laatste, machtige klap. De leiders van deze aanvallen hebben hun schuilplaats in de ruïnes van Stromgarde, een opvallend symbool van menselijke zwakte.$B$BZoek en dood die Boulderfist-heren en hun sjamanen, hun handlangers, die ons uit deze landen willen verdrijven.",
  o = "Dood 15 Boulderfist Shaman en 10 Boulderfist Lords en ga terug naar Drum Fel in de buitenpost Hammerfall.",
  p = "Ik zie dat je moed eindelijk afneemt. Mijn gevoel over jou klopte blijkbaar: je kracht is niets vergeleken met je grootspraak.$b$bKom bij me terug als de kop van het beest eraf is gehakt, of kom nooit meer terug.",
  c = "Je maakt je volk trots, $N. De dreiging is een stuk kleiner geworden, en ik weet zeker dat we hier in de Highlands zullen gaan bloeien.",
  g = { {"geweld", "force, violence"}, {"klap", "blow"}, {"schuilplaats", "lair, hiding place"}, {"opvallend", "glaring, striking"}, {"zwakte", "frailty, weakness"}, {"handlangers", "lackeys (handlanger)"}, {"verdrijven", "drive out"}, {"afneemt", "wanes, decreases (afnemen)"}, {"grootspraak", "bravado, boasting"}, {"gehakt", "chopped, severed (hakken)"}, {"dreiging", "threat"}, {"bloeien", "thrive, bloom"} },
},

[680] = { en = "The Real Threat", tier = 3,
  t = "De echte dreiging",
  d = "Je dient mijn man goed, $c, maar hij weet niet waarom Hammerfall wordt aangevallen.$B$BOr'Kalar, de pion van Mug'thol in Stromgarde, haat mijn man diep. Hij wil niets liever dan de dood van mijn man, omdat mijn man hem jaren geleden heeft verslagen.$B$BMijn voorspellingen vertellen me dat Or'Kalar een val voor mijn man heeft gezet. Daarom heb ik de tekenen dat de ogre hier is voor hem verborgen.$B$BMijn man zal dom op pad stormen als hij hoort waar de ogre is. Daarom vraag ik jou om me te helpen dit wezen te doden.",
  o = "Dood Or'Kalar en breng zijn Head naar Korin Fel in de buitenpost Hammerfall.",
  p = "Bij de Tower of Arathor: daar vind je Or'Kalar. Zijn dood zal de aanvallen op Hammerfall stoppen en het leven van mijn man beschermen.$B$BIk zie in je ogen dat je me zwak vindt, zelfs oneervol, omdat ik zwijg. Op een dag zul je leren wat het is om lief te hebben zoals ik. Misschien begrijp je dan een ander soort kracht en eer.$B$BDoe intussen wat ik vraag, en dood Or'Kalar.",
  c = "Je hebt me een grote dienst bewezen, $N. Weet dat het leven van mijn man en de veiligheid van Hammerfall door jouw daden weer een dag beschermd zijn. Neem dit alsjeblieft als beloning voor je moed.",
  g = { {"pion", "pawn"}, {"verslagen", "defeated (verslaan)"}, {"voorspellingen", "auguries, predictions (voorspelling)"}, {"val", "trap"}, {"tekenen", "signs (teken)"}, {"stormen", "rush, storm"}, {"oneervol", "dishonorable"}, {"zwijg", "am silent (zwijgen)"}, {"intussen", "in the meantime"}, {"dienst bewezen", "done a service (een dienst bewijzen)"}, {"daden", "deeds (daad)"} },
},

[688] = { en = "Myzrael's Allies", tier = 3,
  t = "De bondgenoten van Myzrael",
  d = "<Myzrael spreekt.>$B$BVrij! IK BEN VRIJ! Ik ben vrij om kracht te verzamelen, verborgen voor mijn bewakers. Want als ze nu tegenover me stonden, zouden ze me zeker overmeesteren en opnieuw opsluiten.$B$BMaar op een dag zal ik het tegen de reuzen opnemen, en dan zullen ze spijt hebben dat ze mij hebben bewaakt!$B$BJe bent een edele bondgenoot, $N. Ik zal je later opnieuw nodig hebben. Als ik er klaar voor ben, moet jij me naar de oppervlakte oproepen.$B$BPraat met Zaruk in Hammerfall. Hij weet hoe ik kan worden opgeroepen.",
  o = "Praat met Zaruk in Hammerfall.",
  c = "Welkom, $C. De Vrouwe heeft me verteld dat je zou komen. Als we haar terug naar de oppervlakte willen brengen, dan hebben we veel te bespreken...",
  g = { {"bondgenoten", "allies (bondgenoot)"}, {"bewakers", "captors, guards (bewaker)"}, {"overmeesteren", "overpower"}, {"opsluiten", "imprison, lock up"}, {"het tegen de reuzen opnemen", "confront the giants (het opnemen tegen)"}, {"spijt", "regret"}, {"bewaakt", "guarded (bewaken)"}, {"edele", "noble (edel)"}, {"oppervlakte", "surface"}, {"oproepen", "summon"}, {"Vrouwe", "Lady (title)"} },
},

[2756] = { en = "The Old Ways", tier = 3,
  t = "De oude gewoontes",
  d = "In de tijd van de legenden verbrijzelde Aturk de schedels van zijn vijanden en maalde hij het bot tot fijn poeder, voor gebruik in gloeidraad. Die dagen zijn al lang voorbij, $r. De Warchief vraagt om vrede tussen de clans. Oude vijanden worden nu alleen nog met vermoeide ogen in de gaten gehouden!$B$BOngelooflijk, ik weet het, maar dat is de wil van Thrall.$B$BGenoeg geklaagd! Je bent hier om te leren, en leren zul je! Breng me vier steel breastplates en vier steel helms en je krijgt een voorproefje van oorlog!",
  o = "Breng vier Steel Breastplates en vier Steel Plate Helms naar Aturk the Anvil in Orgrimmar.$b",
  p = "Aturk wacht, net als de tijd, op niemand! Schiet op, dwaas!",
  c = "Je bent blijkbaar ook maar een gemakzuchtige meeloper van de Warchief, $N. Wat een teleurstelling.$b$bWat verlang ik naar een glorieuze dood op het slagveld. In plaats daarvan zit ik hier vast, op bevel van Thrall, om baby's te leren hoe ze iets moeten maken! Kijk en leer, kind!",
  g = { {"gewoontes", "ways, customs (gewoonte)"}, {"verbrijzelde", "crushed (verbrijzelen)"}, {"maalde", "ground (malen)"}, {"poeder", "powder"}, {"gloeidraad", "filament"}, {"vermoeide", "weary (vermoeid)"}, {"in de gaten gehouden", "watched (in de gaten houden)"}, {"geklaagd", "lamented, complained (klagen)"}, {"voorproefje", "foretaste, taste"}, {"gemakzuchtige", "complacent (gemakzuchtig)"}, {"meeloper", "follower, lemming"}, {"teleurstelling", "disappointment"}, {"verlang", "long for (verlangen)"}, {"slagveld", "battlefield"} },
},

[2757] = { en = "Booty Bay or Bust!", tier = 3,
  t = "Booty Bay of niks!",
  d = "Luister, kind, je gaat hier niks leren als je alleen maar wat rondhangt.$B$BIk ken iemand die iemand kent. Hij hangt rond bij de smidse in Booty Bay. Als je hem dit insigne laat zien, vertelt hij je alles over mithril.$B$BDus, wat zeg je ervan? Laat dit kinderwerk over aan de baby's in luiers, $N. Het is tijd om verder te gaan.$B$BAls je interesse hebt: hij heet McGavan. Laat hem deze snuisterij zien en hij zal je toewijding herkennen.",
  o = "Praat met McGavan in Booty Bay.",
  p = "Jouw soort is zeldzaam, maatje. Laat me dat insigne eens zien.",
  c = "Bij het rughaar van Blackhoof... eindelijk iemand die de Mithril Order waardig is!$b$b",
  g = { {"rondhangt", "hang around (rondhangen)"}, {"smidse", "smithy"}, {"insigne", "insignia"}, {"kinderwerk", "kid stuff"}, {"luiers", "diapers (luier)"}, {"snuisterij", "trinket"}, {"toewijding", "commitment, dedication"}, {"herkennen", "recognize"}, {"zeldzaam", "rare"}, {"maatje", "matey, buddy"}, {"rughaar", "back hair"}, {"waardig", "worthy"} },
},

[5301] = { en = "The Art of the Armorsmith", tier = 3,
  t = "De kunst van de pantsersmid",
  d = "Voldoening. Dat haal ik uit de hamer en het aambeeld. Als ik een trotse krijger van de Horde beschermd zie onder mijn staal, herinnert me dat eraan wat het is om te leven. Het is een verslaving die ik nooit durf op te geven, $N.$B$BIk kan je deze voldoening niet geven. Ik kan je alleen op het pad zetten. Zoals alles wat je in het leven onderneemt, is het pad van de pantsersmid een reis.$B$BAls je een van de weinige uitverkorenen wilt zijn, hoef je het alleen maar te vragen en dan zal ik je opleiden. Maar eerst moet je een taak volbrengen.",
  o = "Om pantsersmid te worden, moet je de volgende voorwerpen maken en naar Okothos brengen: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.",
  p = "Ik zal het staal blijven slaan tot de adem zelf uit me is weggenomen.",
  c = "Dit is de laatste stap voordat je aan je nieuwe loopbaan als pantsersmid begint, $N. Als je je wilt terugtrekken, is dit je laatste kans. Bereid je anders voor op een leven vol glorie.",
  g = { {"pantsersmid", "armorsmith"}, {"voldoening", "satisfaction"}, {"aambeeld", "anvil"}, {"verslaving", "addiction"}, {"onderneemt", "undertake (ondernemen)"}, {"uitverkorenen", "chosen ones, select few (uitverkorene)"}, {"opleiden", "train"}, {"volbrengen", "complete, accomplish"}, {"adem", "breath"}, {"loopbaan", "career"}, {"terugtrekken", "back out, withdraw"} },
},

[5302] = { en = "The Way of the Weaponsmith", tier = 3,
  t = "De weg van de wapensmid",
  d = "Op een dag zal ik een legendarische hamer maken. Een hamer die een Warchief waardig is!$B$BHet is mijn levenswerk, $N. Mijn passie. Ik zie dat je het in je hebt om bij ons te horen, een van ons te zijn: een wapensmid. Ik ben degene die je kan helpen om dat talent te benutten.$B$BEen eenvoudige taak is alles wat je moet volbrengen. Eenvoudig voor iemand met jouw uitzonderlijke vaardigheid.",
  o = "Om wapensmid te worden, moet je de volgende voorwerpen maken en naar Borgosh brengen: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes en 2 Big Black Maces.$b",
  p = "Voor de glorie van de Horde!",
  c = "Dit is de laatste stap voordat je aan je nieuwe loopbaan als wapensmid begint, $N. Als je je wilt terugtrekken, is dit je laatste kans. Bereid je anders voor om door kennis te worden verzwolgen!",
  g = { {"wapensmid", "weaponsmith"}, {"legendarische", "legendary (legendarisch)"}, {"waardig", "worthy, fit for"}, {"levenswerk", "life's work"}, {"het in je hebt", "have it in you, have the potential"}, {"benutten", "harness, make use of"}, {"volbrengen", "complete"}, {"uitzonderlijke", "exceptional (uitzonderlijk)"}, {"vaardigheid", "skill"}, {"loopbaan", "career"}, {"verzwolgen", "consumed, swallowed (verzwelgen)"} },
},

[643] = { en = "Sigil of Arathor", tier = 3,
  t = "Het zegel van Arathor",
  d = "Ze hebben Stromgarde nauwelijks in hun macht, laat staan heel Arathi Highlands. Toch laat de menselijke prins de resten van zijn cavalerie over het platteland draven. Ik begrijp niet waarom hij dat doet, maar wie begrijpt nou hoe mensen denken, hm?$b$bWat zijn reden ook is, belangrijker is dat hij een van de zegels aan Lieutenant Valorcall heeft gegeven, de leider van hun cavalerie. Zoek hem en breng zijn zegel naar mij terug.",
  o = "Haal de Sigil of Arathor op en breng hem terug naar Zengu in Hammerfall.",
  p = "Valorcall zal niet makkelijk te vinden zijn, $N. Te paard kan hij snel een grote afstand afleggen. Toch moeten we zijn zegel hebben.",
  c = "Het verlies van hun cavalerieleider wordt een zware klap voor de verdedigers van Stromgarde. Nog beter: het betekent dat we nog maar één zegel nodig hebben om Trol'kalar zelf in handen te krijgen.",
  g = { {"zegel", "sigil, seal"}, {"nauwelijks", "barely"}, {"laat staan", "let alone"}, {"resten", "remnants (rest)"}, {"cavalerie", "cavalry"}, {"platteland", "countryside"}, {"draven", "trot"}, {"te paard", "on horseback"}, {"afstand afleggen", "cover a distance"}, {"verlies", "loss"}, {"verdedigers", "defenders (verdediger)"}, {"in handen te krijgen", "to get hold of (in handen krijgen)"} },
},

[644] = { en = "Sigil of Trollbane", tier = 3,
  t = "Het zegel van Trollbane",
  d = "Het laatste zegel dat nodig is om het graf van Thoras Trollbane te openen, is in handen van zijn zoon zelf. Hij woont diep in Stromgarde, in een kapel in de wijken die de militie in handen heeft. Prince Galen wordt goed beschermd en is zelf ook zeker geen slechte krijger, dus deze taak kan heel moeilijk blijken.",
  o = "Dood Prince Galen Trollbane en breng de Sigil of Trollbane naar Zengu in Hammerfall.",
  p = "Je bent terug, $N. Is de familielijn van Ignaeus Trollbane verbroken?",
  c = "Wat een dag is dit, $C. Het bloed van Trollbane zal mijn volk niet langer kwellen, en de zegels die nodig zijn om Trol'kalar te nemen zijn in ons bezit. Binnenkort, heel binnenkort, slaan we toe tegen de gehate trollen van Zul'Gurub.",
  g = { {"graf", "tomb, grave"}, {"kapel", "chapel"}, {"wijken", "districts (wijk)"}, {"militie", "militia"}, {"blijken", "prove, turn out"}, {"familielijn", "family line"}, {"verbroken", "broken (verbreken)"}, {"kwellen", "haunt, torment"}, {"bezit", "possession"}, {"slaan we toe", "we strike (toeslaan)"}, {"gehate", "hated (gehaat)"} },
},

[645] = { en = "Trol'kalar", tier = 3,
  t = "Trol'kalar",
  d = "Wat is dit? Nu de vier zegels bij elkaar zijn, zijn ze samengesmolten tot één zegel. Zonder twijfel kan dit de beschermende spreuken op het graf van Trollbane breken.$b$bDe resten van Trollbane liggen begraven in het Sanctum achter de kapel in Stromgarde. Haal Trol'kalar op.",
  o = "Haal Trol'kalar uit het graf van Trollbane in Stromgarde.",
  p = "De inkervingen in de steen op de voorkant van het graf van Trollbane komen overeen met de gloeiende lijnen van de Sigil of Ignaeus...",
  c = "Je legt de lijnen op de voorkant van het graf van Trollbane gelijk met de gloeiende lijnen van de Sigil of Ignaeus. Een lichtflits verslindt het zegel, en het legendarische zwaard Trol'kalar komt los uit de greep van de stenen handen.",
  g = { {"samengesmolten", "fused, merged (samensmelten)"}, {"beschermende", "protective (beschermend)"}, {"spreuken", "spells, wards (spreuk)"}, {"begraven", "buried, entombed"}, {"inkervingen", "etchings, carvings (inkerving)"}, {"komen overeen", "match (overeenkomen)"}, {"gloeiende", "glowing (gloeiend)"}, {"lichtflits", "flash of light"}, {"verslindt", "consumes, devours (verslinden)"}, {"legendarische", "legendary (legendarisch)"}, {"greep", "grip"} },
},

[1048] = { en = "Into The Scarlet Monastery", tier = 3,
  t = "Het Scarlet Monastery in",
  d = "Terwijl de Dark Lady zich bezighoudt met het dringende probleem van de opmars van de Lich King in het noorden, zorg ik ervoor dat zaken dichter bij huis op de juiste manier worden afgehandeld.$b$bZonder twijfel is het menselijke ongedierte dat zich de Scarlet Crusade noemt in eigen land de scherpste doorn in ons oog. Tirisfal Glades krioelt letterlijk van die kleine rode mieren.$b$bReis naar het klooster, $c, en vernietig High Inquisitor Whitemane en haar belangrijkste luitenants.",
  o = "Dood High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion en Houndmaster Loksey en ga dan terug naar Varimathras in Undercity.",
  p = "Misschien waren mijn bevelen niet duidelijk genoeg, $c. Ik wil dat High Inquisitor Whitemane voor eens en altijd wordt gedood. En als je toch bezig bent, ruim dan ook haar hoogste officieren op.$b$bDood die fanaticus, Scarlet Commander Mograine. Vernietig Herod, the Scarlet Champion. En slacht Houndmaster Loksey af, en zijn smerige honden ook.$b$bGa nu!",
  c = "Je hebt de Dark Lady goed gediend, $c. Het was geen kleine taak die ik je gaf.$b$bJe trouw aan de Forsaken is opgemerkt. En je volharding in de strijd zal niet vergeten worden.",
  g = { {"zich bezighoudt", "is occupied with (zich bezighouden)"}, {"dringende", "pressing, urgent (dringend)"}, {"opmars", "advance"}, {"afgehandeld", "taken care of (afhandelen)"}, {"ongedierte", "pests, vermin"}, {"doorn in ons oog", "thorn in our side (idiom)"}, {"krioelt", "is crawling, swarms (krioelen)"}, {"voor eens en altijd", "once and for all"}, {"ruim ... op", "take out, clear away (opruimen)"}, {"fanaticus", "zealot"}, {"slacht ... af", "slaughter (afslachten)"}, {"trouw", "loyalty"}, {"opgemerkt", "noted (opmerken)"}, {"volharding", "tenacity, perseverance"} },
},

[8438] = { en = "Conquering Arathi Basin", tier = 4,
  t = "De verovering van Arathi Basin",
  d = "Ons conflict met de Alliance is uitgegroeid tot een echte oorlog. Geen van beide kanten gebruikt of verwacht op dit moment nog valse voorwendsels om de strijd aan te gaan.$B$BDe strijd om Arathi Basin draait om grondstoffen, zo simpel is het. Óf de Alliance krijgt de grondstoffen en gebruikt ze tegen ons, óf wij krijgen ze en gebruiken ze om onze oorlogsinspanningen voort te zetten. Help de Defilers om de stroom grondstoffen die we nodig hebben op gang te houden, $N!",
  o = "Breng 3 Arathi Basin Mark of Honor naar een Horde Warbringer buiten de slagvelden.",
  p = "Ben je terug met nieuws uit Arathi, $C?",
  c = "Het veiligstellen van onze grondstoffen in Arathi is een belangrijke taak! Je hebt het goed gedaan, $N.",
  g = { {"verovering", "conquest"}, {"uitgegroeid", "grown into, escalated (uitgroeien)"}, {"voorwendsels", "pretenses, pretexts (voorwendsel)"}, {"de strijd aan te gaan", "to enter into battle (de strijd aangaan)"}, {"draait om", "is about (draaien om)"}, {"grondstoffen", "resources, raw materials (grondstof)"}, {"oorlogsinspanningen", "war efforts (oorlogsinspanning)"}, {"op gang te houden", "to keep going (op gang houden)"}, {"slagvelden", "battlegrounds (slagveld)"}, {"veiligstellen", "securing (veiligstellen)"} },
},

})

